import re

from datetime import datetime

from taf.rfrl.l3_call.btslog.btslog import BtsLog


class NrBtsLog(BtsLog):
    def __init__(self, duration, direction, throughput, deviation, cell_id, logfile_path):
        super().__init__(duration, direction, throughput, deviation, cell_id, logfile_path)
        self._seconds_offset = 2

    def _parse_dl_tput_value(self, line, start_timestamp, stop_timestamp):
        if "DL-RLC numOfBearers:1" in line:
            timestamp = datetime.strptime(line.split(" ")[2], "%H:%M:%S.%f")
            if start_timestamp <= timestamp <= stop_timestamp:
                for index, element in enumerate(line.split(" ")):
                    if "inB:" in element:
                        return int(element.split(":")[-1].strip(","))

    def _parse_ul_tput_value(self, line, start_timestamp, stop_timestamp):
        if re.match(r".*UlCounterUpdate\.cpp:\d+/UL.*", line):
            if f"nrCellIdentity {str(self._cell_id)}" in line:
                timestamp = datetime.strptime(line.split(" ")[2], "%H:%M:%S.%f")
                if start_timestamp <= timestamp <= stop_timestamp:
                    return int(line.split(" ")[10])
